const __pageData = JSON.parse('{"title":"自定义starter","description":"把前两篇学的起步依赖与自动配置合起来用一次——做一个自己的公共组件 starter（依赖管理功能 + 自动配置功能），按「建 starter 模块、建 autoconfigure 模块、写自动配置类并登记到 imports 文件」三步落地，附本机 install 两个模块后只加一行依赖就能注入工具类的实测，末尾交代 3.2.x 与老版本读文件方式的差异","frontmatter":{"title":"自定义starter","published":"2026-09-29T00:00:00.000Z","description":"把前两篇学的起步依赖与自动配置合起来用一次——做一个自己的公共组件 starter（依赖管理功能 + 自动配置功能），按「建 starter 模块、建 autoconfigure 模块、写自动配置类并登记到 imports 文件」三步落地，附本机 install 两个模块后只加一行依赖就能注入工具类的实测，末尾交代 3.2.x 与老版本读文件方式的差异","tags":["JavaWeb","SpringBoot","Maven"],"image":"https://img.tsh520.cn/file/blog/post-covers/javaweb-90-custom-starter.webp","order":90,"date":"2026-09-29T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/JavaWeb学习笔记/90-自定义starter.md","filePath":"posts/学习文档/JavaWeb学习笔记/90-自定义starter.md"}');
